CREATE TABLE IF NOT EXISTS panas_accounting_ledger (ledger_id uuid PRIMARY KEY, request_id uuid REFERENCES panas_accounting_requests(request_id), idempotency_key text NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN ('fund','settle','refund')), currency text NOT NULL DEFAULT 'TEST_CREDIT' CHECK(currency='TEST_CREDIT'), entries jsonb NOT NULL CHECK(panas_accounting_balanced(entries) IS TRUE), created_at timestamptz NOT NULL);
